import React, { useContext, useState } from 'react'
import './CSS/ShopCategory.css'
import { ShopContext } from '../Context/ShopContext'
import Item from '../Components/Items/Item'

const ShopCategory = (props) => {
  const { all_product } = useContext(ShopContext)
  const [sortOrder, setSortOrder] = useState("default")

  let filteredProducts = all_product.filter(
    (item) => props.category === item.category
  )

  if (sortOrder === "lowToHigh") {
    filteredProducts.sort((a, b) => a.new_price - b.new_price)
  } else if (sortOrder === "highToLow") {
    filteredProducts.sort((a, b) => b.new_price - a.new_price)
  }

  // Category එක අනුව වෙනස් වන Text සහ Image එක (Error එකක් එන්නේ නැති වෙන්න Image Links දැම්මා)
  // ඔයාට ඕන නම් මෙතන තියෙන Links වෙනුවට ඔයාගේ ලඟ තියෙන ඕනෑම Image Link එකක් දෙන්න පුළුවන්.
  const getBannerDetails = () => {
    switch(props.category) {
      case "men":
        return { 
          title: "MEN'S COLLECTION", 
          desc: "Upgrade your style with premium essentials",
          image: filteredProducts[0]?.image || "https://images.unsplash.com/photo-1617137968427-85924c800a22?q=80&w=500"
        };
      case "women":
        return { 
          title: "WOMEN'S TRENDS", 
          desc: "Discover elegance in every single detail",
          image: filteredProducts[0]?.image || "https://images.unsplash.com/photo-1539109136881-3be0616acf4b?q=80&w=500" 
        };
      case "kids":
        return { 
          title: "KIDS' FASHION", 
          desc: "Comfortable and playful styles for little ones",
          image: filteredProducts[0]?.image || "https://images.unsplash.com/photo-1519457431-44ccd64a579b?q=80&w=500" 
        };
      default:
        return { 
          title: "EXCLUSIVE DESIGNS", 
          desc: "Flat 50% OFF on all trending items",
          image: null 
        };
    }
  }

  const bannerInfo = getBannerDetails();

  return (
    <div className='shop-category'>
      
      {/* Creative Banner Structure */}
      <div className="shopcategory-banner">
        <div className="shopcategory-banner-text">
          <h2>{bannerInfo.title}</h2>
          <h1>FLAT <span>50% OFF</span></h1>
          <p>{bannerInfo.desc}</p>
          <button>SHOP THE SALE</button>
        </div>
        
        {/* දකුණු පැත්තේ පෙනෙන Image Wrapper එක */}
        {bannerInfo.image && (
          <div className="shopcategory-banner-image">
            <img src={bannerInfo.image} alt={`${props.category} banner`} />
          </div>
        )}
      </div>

      <div className="shopcategory-indexSort">
        <p>
          <span>Showing 1-12</span> out of {filteredProducts.length} products
        </p>

        <select
          className="shopcategory-sort"
          onChange={(e) => setSortOrder(e.target.value)}
          value={sortOrder}
        >
          <option value="default">Default</option>
          <option value="lowToHigh">Low to High</option>
          <option value="highToLow">High to Low</option>
        </select>
      </div>

      <div className="shopcategory-products">
        {filteredProducts.map((item, i) => (
          <Item
            key={i}
            id={item.id}
            name={item.name}
            image={item.image}
            new_price={item.new_price}
            old_price={item.old_price}
          />
        ))}
      </div>

      <div className="shopcategory-loadmore">
        Explore More
      </div>
    </div>
  )
}

export default ShopCategory
